</perturbed_code_3>
<perturbed_code_4>
<your_rewritten_code_4>
</perturbed_code_4>
<perturbed_code_5>
<your_rewritten_code_5>
</perturbed_code_5>
Each block must contain one complete program. Do not provide any other text or markdown fences.

Here is the original GNU C++0x code you have to rewrite:
<original_code>
//http://codeforces.com/problemset/problem/281/B
/**/
#include<bits/stdc++.h>
using namespace std;

#define pb push_back
#define FOR(i, begin, end) for(__typeof(end) i = (begin); i < (end); i++)
#define For(i, begin, end) for (__typeof(end) i = (begin) - ((begin) > (end)); i != (end) - ((begin) > (end)); i += 1 - 2 * ((begin) > (end)))
#define all(v) v.begin(),v.end()
#define minv(v) min_element(all(v))
#define maxv(v) max_element(all(v))
#define V vector
typedef long long ll;
/***********************************************/
/* Dear online judge:
 * I've read the problem, and tried to solve it.
 * Even if you don't accept my solution, you should respect my effort.
 * I hope my code compile and get accepted. O.o
 *      ____________
 *     /         __ \
 *    /   __    |  | \
 *   /   |__|   |  |  \
 *  (           |__|   )
 *   \                /
 *    \      ___     /
 *     \____________/
 */
const ll mod = 1000000009;
int main(){
    ios_base::sync_with_stdio(false);
    //cin.tie(nullptr);
    ll n,res,cur,resd,x,y;
    cin>>x>>y>>n;
    cur = __gcd(x,y);
    x/=cur;
    y/=cur;
    res = 1e9;
    resd = 1;
    if(y <= n){
        cout<<x<<'/'<<y<<endl;
        return 0;
    }
    FOR(i,1,n+1){
        cur = floor((x*i)/y);
        if(resd * abs(x * i - cur * y) < i * abs(x * resd - res * y)){
            resd = i;
            res = cur;
        }
        cur++;
        if(resd * abs(x * i - cur * y) < i * abs(x * resd - res * y)){
            resd = i;
            res = cur;
        }
    }
    cout<<res<<'/'<<resd;
    return 0;
}
